"""R204: Diff of T_w vs scaled 2p*T_w (quaternion algebra generated by two trace-zero elements with Gram lam*T is
(-lam*A*, -det T * A*) up to squares).  Zhu (arXiv 2304.10696) uses Delta(N) = {[[-Na,b],[c,a]]}, Q = det, whose
Q_l-span is N*(M2^{tr=0}, det); so Diff(T, Delta(N)) = Ram(algebra of T/N).  Prints how often Ram(T_w/(2p)) differs
from Ram(T_w) on words of primes p."""
import sys
sys.path.insert(0, "scripts")
from review_si_lemmas import hilbert, factor, words_bruteforce, jacobi
from fractions import Fraction

def ram(a, b):
    S = set(factor(abs(a))) | set(factor(abs(b))) | {2}
    return {p for p in S if hilbert(a, b, p) == -1}

tot = diff = 0
ex = []
for p in range(3, 400):
    if any(p % d == 0 for d in range(2, int(p**0.5) + 1)):
        continue
    for (t, u, v) in words_bruteforce(p):
        A, As = t*u - 1, t*v - 1
        r0 = ram(-As, -t*p*As)
        # Gram T/N, N=2p: generators i' with i'^2 = -As/N; algebra (-As/N, -det(T/N)*(As/N)) ~ (-As*N, -t*p*As) mod squares
        N = 2*p
        r1 = ram(-As*N, -t*p*As*N)
        tot += 1
        if r0 != r1:
            diff += 1
            if len(ex) < 5: ex.append(((t,u,v), p, sorted(r0), sorted(r1)))
print(f"words of primes p<400: {tot}; Ram(T_w) != Ram(T_w/2p): {diff}; examples {ex}")
